import{_ as t,o,c as i,a2 as n}from"./chunks/framework.CFOYCmPM.js";const g=JSON.parse('{"title":"Chapter 7: In-Editor Playtesting with the Docked Game Viewport","description":"","frontmatter":{},"headers":[],"relativePath":"guide/in-editor-testing.md","filePath":"guide/in-editor-testing.md","lastUpdated":null}'),a={name:"guide/in-editor-testing.md"};function r(s,e,l,d,c,h){return o(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="chapter-7-in-editor-playtesting-with-the-docked-game-viewport" tabindex="-1">Chapter 7: In-Editor Playtesting with the Docked Game Viewport <a class="header-anchor" href="#chapter-7-in-editor-playtesting-with-the-docked-game-viewport" aria-label="Permalink to &quot;Chapter 7: In-Editor Playtesting with the Docked Game Viewport&quot;">​</a></h1><p>One of the most powerful features of DayZ Studio is the <strong>Docked In-Engine Viewport</strong>. You never have to guess how your outpost looks or how your quests feel in the real game engine.</p><hr><h2 id="⚡-the-instant-testing-loop" tabindex="-1">⚡ The Instant Testing Loop <a class="header-anchor" href="#⚡-the-instant-testing-loop" aria-label="Permalink to &quot;⚡ The Instant Testing Loop&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Traditional Testing Workflow (Slow):</span></span>
<span class="line"><span>[Edit Code] ➔ [Repack PBO] ➔ [Sign Key] ➔ [Copy to Server] ➔ [Restart Server] ➔ [Launch DayZ] (5–10 Minutes)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>DayZ Studio Testing Workflow (Instant):</span></span>
<span class="line"><span>[Edit in Studio] ➔ [Switch to Game Tab] ➔ [Walk Around Immediately] (&lt;10 Seconds)</span></span></code></pre></div><hr><h2 id="🎮-how-the-docked-viewport-works" tabindex="-1">🎮 How the Docked Viewport Works <a class="header-anchor" href="#🎮-how-the-docked-viewport-works" aria-label="Permalink to &quot;🎮 How the Docked Viewport Works&quot;">​</a></h2><ol><li>Switch to the <strong>Game</strong> tab (<code>Alt + 2</code>).</li><li>DayZ Studio boots a borderless, offline DayZ client embedded directly inside the editor layout.</li><li><strong>Active Central Economy (CE):</strong> Loot spawns dynamically in buildings, wild animals roam the wilderness, and infected populate towns.</li><li><strong>Sub-Second Live Synchronization:</strong> Move an object in DayZ Studio, and its position updates in the running game viewport in <strong>under one second</strong>!</li><li><strong>Bidirectional Selection:</strong> Click an object inside the game window, and it highlights inside Studio&#39;s Inspector.</li><li><strong>Live Quest Beacons:</strong> Translucent trigger cylinders, interaction pillars, and flow lines render visibly inside the game viewport so you can visually confirm your quest trigger radiuses.</li></ol><hr><h2 id="🕹️-in-game-testing-shortcuts" tabindex="-1">🕹️ In-Game Testing Shortcuts <a class="header-anchor" href="#🕹️-in-game-testing-shortcuts" aria-label="Permalink to &quot;🕹️ In-Game Testing Shortcuts&quot;">​</a></h2><ul><li><strong>Standard Controls:</strong> Walk in 1st/3rd person using <code>WASD</code> and mouse look.</li><li><strong>Camera Focus (<code>F</code>):</strong> Fly the camera directly to your currently selected studio prop.</li><li><strong>Teleport (<code>tp</code>):</strong> Type <code>tp &lt;location&gt;</code> or coordinates in the floating console (\`Ctrl + \`\`) to teleport anywhere on the map instantly.</li><li><strong>Toggle CE:</strong> You can toggle <strong>🎒 Loot &amp; infected</strong> off anytime in the toolbar if you prefer a peaceful environment while arranging buildings.</li></ul><hr><h2 id="🌐-local-dedicated-multiplayer-server" tabindex="-1">🌐 Local Dedicated Multiplayer Server <a class="header-anchor" href="#🌐-local-dedicated-multiplayer-server" aria-label="Permalink to &quot;🌐 Local Dedicated Multiplayer Server&quot;">​</a></h2><p>Need to verify multiplayer RPCs, player reconnection, or BattlEye compliance?</p><ul><li>In the toolbar, click <strong>Test on local server</strong>.</li><li>DayZ Studio launches a real local <code>DayZServer_x64.exe</code> instance with your mod loaded.</li><li>Click <strong>② Join with the game</strong> to launch the DayZ client with BattlEye security enabled and verify multiplayer functionality.</li></ul>`,15)])])}const u=t(a,[["render",r]]);export{g as __pageData,u as default};
